import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    """
    Extract regex matches from all .txt files in the given directory.

    Returns:
        dict: Mapping of filename (without path) to list of regex matches.
    """
    result = {}
    directory = Path(directory_path)

    if not directory.exists() or not directory.is_dir():
        return result

    # Normalize the supplied default pattern, which may arrive double-escaped
    # in the task text.
    effective_pattern = regex_pattern
    if regex_pattern == r'\\(.+?\\)|\\w':
        effective_pattern = r'\(.+?\)|\w'

    try:
        compiled = re.compile(effective_pattern)
    except re.error:
        # Fallback to the original pattern if normalization was not valid.
        try:
            compiled = re.compile(regex_pattern)
        except re.error:
            return result

    file_paths = sorted(glob.glob(os.path.join(str(directory), "*.txt")))

    for file_path in file_paths:
        path = Path(file_path)
        if not path.is_file():
            continue

        try:
            content = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        result[path.name] = [match.group(0) for match in compiled.finditer(content)]

    return result
